//! Admitted source-borrowed projection of the EXISTING checker report order.
use super::*;
use crate::{checker_effects::{ExecutionAdmission,output::ReportBudget},policy_body_demand::PolicyFailure};
use std::{cmp::Ordering,io,mem::size_of};
struct OrderedRow<'a>{path:&'a str,first:usize,override_value:bool,occurrence:u32,ordinal:usize}
pub(crate) struct ArchivedOrder<'a>{rows:Vec<OrderedRow<'a>>}
impl<'a> ArchivedOrder<'a>{
 pub(crate) fn len(&self)->usize{self.rows.len()}
 pub(crate) fn retained_charge(&self)->Option<usize>{std::mem::size_of::<Self>().checked_add(self.rows.capacity().checked_mul(std::mem::size_of::<OrderedRow<'_>>())?)}
 pub(crate) fn ordinal(&self,index:usize)->Option<usize>{Some(self.rows.get(index)?.ordinal)}
 pub(crate) fn build(archive:&'a dm_tree::frontend::BodyArchive,admission:&ExecutionAdmission,checkpoint:&mut impl FnMut()->io::Result<()>,work:&mut impl FnMut(usize)->io::Result<()>)->Result<Self,PolicyFailure>{
  checkpoint().map_err(PolicyFailure::Operational)?;admission.reserve_external(0).map_err(PolicyFailure::Operational)?;
  let pending=(||{
  if !archive.callables().authenticates_borrowed_tree(archive.tree()){return Err("checker order has foreign original callable roster".into())}let tree=archive.tree();let budget=ReportBudget::for_operation(admission);let mut count=0usize;super::visit_callable_declarations::<PolicyFailure>(tree,||checkpoint().map_err(PolicyFailure::Operational),|_,_,_|{count=count.checked_add(1).ok_or_else(||deny(&budget,"checker order group count overflow"))?;Ok(())})?;
  let mut groups=allocate::<(dm_ir::TypeId,dm_ir::SymbolId,usize)>(count,&budget,work)?;super::visit_callable_declarations::<PolicyFailure>(tree,||checkpoint().map_err(PolicyFailure::Operational),|owner,name,index|{groups.push((owner,name,index));Ok(())})?;
  heapsort(&mut groups,&mut|left,right|{checkpoint().map_err(PolicyFailure::Operational)?;Ok(left.cmp(right))})?;groups.dedup_by(|right,left|right.0==left.0&&right.1==left.1);
  let mut rows=allocate(archive.len(),&budget,work)?;for(ordinal,body)in archive.occurrences().iter().enumerate(){checkpoint().map_err(PolicyFailure::Operational)?;let member=tree.member(body.member).ok_or("checker body member absent")?;let owner=tree.type_node(member.owner).ok_or("checker body owner absent")?;let path=tree.symbols().text(owner.path).ok_or("checker owner path absent")?;let first=groups.binary_search_by_key(&(member.owner,member.name),|row|(row.0,row.1)).ok().map(|at|groups[at].2).ok_or("checker callable encounter absent")?;let occurrence=archive.callables().identity(ordinal).ok_or("checker callable occurrence absent")?.occurrence;rows.push(OrderedRow{path,first,override_value:member.definition!=DefinitionMode::Declare,occurrence,ordinal});}
  heapsort(&mut rows,&mut|left,right|{checkpoint().map_err(PolicyFailure::Operational)?;Ok(path_order(left.path,right.path,checkpoint)?.then_with(||(left.first,left.override_value,left.occurrence,left.ordinal).cmp(&(right.first,right.override_value,right.occurrence,right.ordinal))))})?;drop(groups);checkpoint().map_err(PolicyFailure::Operational)?;if admission.is_denied(){return Err(deny(&budget,"checker order operation denied"))}Ok(Self{rows})
 
  })();
  if matches!(&pending,Err(PolicyFailure::Operational(_))){return pending}checkpoint().map_err(PolicyFailure::Operational)?;admission.reserve_external(0).map_err(PolicyFailure::Operational)?;pending
 }
}
fn deny(budget:&ReportBudget,message:&'static str)->PolicyFailure{budget.deny();PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message))}
fn allocate<T>(count:usize,budget:&ReportBudget,work:&mut impl FnMut(usize)->io::Result<()>)->Result<Vec<T>,PolicyFailure>{let bytes=count.checked_mul(size_of::<T>()).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(size_of::<Vec<T>>()+64)).ok_or_else(||deny(budget,"checker order capacity overflow"))?;budget.charge(bytes).map_err(|_|deny(budget,"checker order admission exhausted"))?;work(bytes).map_err(PolicyFailure::Operational)?;let mut rows=Vec::new();rows.try_reserve_exact(count).map_err(|actual|{budget.deny();PolicyFailure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual))})?;if rows.capacity()>count.saturating_mul(4){return Err(deny(budget,"checker order allocator exceeds admitted envelope"))}Ok(rows)}
fn heapsort<T>(rows:&mut[T],compare:&mut impl FnMut(&T,&T)->Result<Ordering,PolicyFailure>)->Result<(),PolicyFailure>{fn sift<T>(rows:&mut[T],mut root:usize,end:usize,compare:&mut impl FnMut(&T,&T)->Result<Ordering,PolicyFailure>)->Result<(),PolicyFailure>{loop{let Some(mut child)=root.checked_mul(2).and_then(|n|n.checked_add(1)).filter(|child|*child<end)else{return Ok(())};if child+1<end&&compare(&rows[child],&rows[child+1])?==Ordering::Less{child+=1}if compare(&rows[root],&rows[child])?!=Ordering::Less{return Ok(())}rows.swap(root,child);root=child;}}let len=rows.len();for start in(0..len/2).rev(){sift(rows,start,len,compare)?}for end in(1..len).rev(){rows.swap(0,end);sift(rows,0,end,compare)?}Ok(())}

#[cfg(test)]mod tests{
 use super::*;use dm_tree::frontend::{build,ColdFrontend};use std::path::Path;
 struct Source(&'static str);impl dm_preprocess::SourceProvider for Source{fn read(&self,_:&Path)->Result<String,String>{Ok(self.0.into())}}
 fn front(source:&'static str)->ColdFrontend{build(Path::new("p.dme"),&Source(source),&Default::default(),1).unwrap()}
 #[test]fn checked_borrowed_order_matches_complete_original_bodyless_groups_and_lexical_preorder(){for source in [include_str!("../../../fixtures/unified_checks/proc_group_order.dm"),"/datum/test/proc/z()\n/datum/test/proc/a()\n    return 0\n/datum/test/z()\n    return 1\n","/datum/z/proc/probe()\n    return 1\n/datum/a\n    parent_type=/datum/z\n/datum/a/probe()\n    return 2\n/datum/a/child\n    parent_type=/datum\n/datum/a/child/proc/probe()\n    return 3\n"]{let front=front(source);let archive=front.body_archive().unwrap();let expected=super::super::archived_bodies(&archive).unwrap().iter().map(|(ordinal,_)|*ordinal).collect::<Vec<_>>();let order=ArchivedOrder::build(&archive,&ExecutionAdmission::default(),&mut||Ok(()),&mut|_|Ok(())).unwrap();assert_eq!((0..order.len()).map(|index|order.ordinal(index).unwrap()).collect::<Vec<_>>(),expected);}}
 #[test]fn checked_order_preserves_actual_io_and_refuses_quota_without_output(){let front=front("/proc/a()\n    return 1\n");let archive=front.body_archive().unwrap();let failure=ArchivedOrder::build(&archive,&ExecutionAdmission::default(),&mut||Ok(()),&mut|_|Err(io::Error::from_raw_os_error(1450))).err().unwrap();assert!(matches!(failure,PolicyFailure::Operational(ref actual)if actual.raw_os_error()==Some(1450)));let tiny=ExecutionAdmission::with_limit(1);assert!(matches!(ArchivedOrder::build(&archive,&tiny,&mut||Ok(()),&mut|_|panic!("quota refuses before external allocation")),Err(PolicyFailure::Operational(ref actual))if actual.kind()==io::ErrorKind::OutOfMemory));assert!(ArchivedOrder::build(&archive,&ExecutionAdmission::default(),&mut||Ok(()),&mut|_|Ok(())).is_ok());}
}

fn path_order(left:&str,right:&str,checkpoint:&mut impl FnMut()->io::Result<()>)->Result<Ordering,PolicyFailure>{let mut left=left.split('/').filter(|part|!part.is_empty());let mut right=right.split('/').filter(|part|!part.is_empty());loop{checkpoint().map_err(PolicyFailure::Operational)?;match(left.next(),right.next()){(Some(a),Some(b))=>{let result=a.cmp(b);if result!=Ordering::Equal{return Ok(result)}},(None,None)=>return Ok(Ordering::Equal),(None,Some(_))=>return Ok(Ordering::Less),(Some(_),None)=>return Ok(Ordering::Greater)}}}

pub(crate) fn sort_report_projection(rows:&mut[usize],rank:&[u32],checkpoint:&mut impl FnMut()->Result<(),PolicyFailure>)->Result<(),PolicyFailure>{heapsort(rows,&mut|left,right|{checkpoint()?;let a=rank.get(*left).ok_or("effect report left rank absent")?;let b=rank.get(*right).ok_or("effect report right rank absent")?;Ok(a.cmp(b))})}
